<?php require_once __DIR__.'/../config/bootstrap.php'; $u=require_login();$cid=(int)($_GET['course']??0);$s=db()->prepare('SELECT c.*,e.id enrollment_id,e.status enrollment_status,e.completed_at FROM courses c JOIN enrollments e ON e.course_id=c.id AND e.user_id=? WHERE c.id=?');$s->execute([$u['id'],$cid]);$c=$s->fetch();if(!$c||$c['enrollment_status']!=='completed')exit('Conclua o curso antes de emitir o certificado.');$q=db()->prepare('SELECT * FROM certificates WHERE user_id=? AND course_id=? AND status="active" LIMIT 1');$q->execute([$u['id'],$cid]);$cert=$q->fetch();if(!$cert){$code='HC-'.random_code(11);$valid=date('Y-m-d',strtotime('+365 days'));$db=db();$db->prepare('INSERT INTO certificates(user_id,course_id,enrollment_id,codigo,validade) VALUES(?,?,?,?,?)')->execute([$u['id'],$cid,$c['enrollment_id'],$code,$valid]);$cert=['codigo'=>$code,'issued_at'=>date('Y-m-d H:i:s'),'validade'=>$valid];}$verify=app_base_url().'/aluno/verificar.php?codigo='.urlencode($cert['codigo']);$qr='https://api.qrserver.com/v1/create-qr-code/?size=180x180&data='.urlencode($verify); ?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Certificado <?=e($cert['codigo'])?></title><style>*{box-sizing:border-box}body{margin:0;background:#e9eef5;font-family:Georgia,serif}.actions{position:fixed;top:20px;right:20px;font-family:Arial;display:flex;gap:10px}.actions button,.actions a{padding:11px 16px;border:0;border-radius:8px;background:#0b4da2;color:#fff;text-decoration:none;cursor:pointer}.certificate{width:1120px;min-height:790px;margin:70px auto;padding:70px;background:#fff;border:18px solid #0b4da2;outline:3px solid #d3aa43;outline-offset:-35px;text-align:center;position:relative}.certificate h1{font-size:46px;color:#0b4da2;margin:30px 0 10px}.certificate h2{font-size:30px;margin:20px}.certificate p{font-size:22px}.student{font-size:34px;font-weight:bold;color:#111;margin:30px}.meta{display:flex;justify-content:space-between;align-items:end;margin-top:55px;font-family:Arial;font-size:13px}.qr{width:120px;height:120px}.line{width:260px;border-top:1px solid #222;margin:0 auto 6px}@media print{.actions{display:none}body{background:#fff}.certificate{margin:0;width:100%;min-height:100vh;page-break-after:always}} </style></head><body><div class="actions"><button onclick="window.print()">Baixar / imprimir PDF</button><a href="<?=e(url('aluno/verificar.php?codigo='.urlencode($cert['codigo'])))?>">Verificar</a></div><div class="certificate"><div>HEAL · CAPACITAÇÃO PROFISSIONAL</div><h1>CERTIFICADO</h1><p>Certificamos que</p><div class="student"><?=e($u['nome'])?></div><p>concluiu o curso</p><h2><?=e($c['titulo'])?></h2><p>com carga horária de <?=e($c['carga_horaria'])?> horas.</p><div class="meta"><div><div class="line"></div>HEAL · Coordenação</div><div><img class="qr" src="<?=e($qr)?>"><div>Código: <?=e($cert['codigo'])?></div><div>Validade: <?=e(date('d/m/Y',strtotime($cert['validade'])))?></div></div></div></div></body></html>
